class Solution {
public:
    string reverseParentheses(string s) {
        int n = s.size();
        vector<int> match(n, -1);
        stack<int> st;
        for (int i = 0; i < n; i++) {
            if (s[i] == '(') {
                st.push(i);
            } else if (s[i] == ')') {
                int j = st.top();
                st.pop();
                match[i] = j;
                match[j] = i;
            }
        }
        string result;
        result.reserve(n);
        int i = 0, dir = 1;
        while (i >= 0 && i < n) {
            if (s[i] == '(' || s[i] == ')') {
                i = match[i];
                dir = -dir;
                i += dir;
            } else {
                result += s[i];
                i += dir;
            }
        }
        return result;
    }
};
